import React from "react";

const Navbar = () => {
  return (
    <header className="navbar bg-gradient-to-r from-purple-500 via-pink-500 to-red-500 text-white">
      <div className="container mx-auto px-4 py-4 flex justify-between items-center">
        {/* Logo */}
        <h1 className="text-2xl font-bold">CampusMarket</h1>

        {/* Navigation Links */}
        <nav className="nav-links flex space-x-6">
          <a href="#features" className="hover:underline">
            Features
          </a>
          <a href="#join" className="hover:underline">
            Join
          </a>
          <a href="#contact" className="hover:underline">
            Contact
          </a>
        </nav>
      </div>
    </header>
  );
};

export default Navbar;
